const raw = $json.body ?? $json;

const src = {};

for (const [key, value] of Object.entries(raw)) {
  src[key.trim()] = value;
}
return [{
  json: {
    alert_id: String(src.alert_id ?? '').trim(),
    timestamp: String(src.timestamp ?? '').trim(),
    source: String(src.source ?? '').trim().toLowerCase(),
    alert_type: String(src.alert_type ?? '').trim().toLowerCase(),
    description: String(src.description ?? '').trim(),

    source_ip: String(src.source_ip ?? '').trim(),
    destination_ip: String(src.destination_ip ?? '').trim(),
    domain: String(src.domain ?? '').trim().toLowerCase(),
    url: String(src.url ?? '').trim(),
    file_hash: String(src.file_hash ?? '').trim().toLowerCase(),
    username: String(src.username ?? '').trim(),
    hostname: String(src.hostname ?? '').trim(),
    original_severity: String(src.original_severity ?? '').trim().toLowerCase(),

    metadata:
      src.metadata &&
      typeof src.metadata === 'object'
        ? src.metadata
        : {},

    input_source: $json.body ? 'webhook' : 'manual'
  }
}];

const requiredFields = [
  'alert_id',
  'timestamp',
  'source',
  'alert_type',
  'description'
];

const errors = [];

for (const field of requiredFields) {
  if (!$json[field]) {
    errors.push(`Missing required field: ${field}`);
  }
}

if (
  $json.timestamp &&
  Number.isNaN(Date.parse($json.timestamp))
) {
  errors.push('timestamp must be a valid date/time');
}

return [{
  json: {
    ...$json,

    validation: {
      valid: errors.length === 0,
      errors
    }
  }
}];

return [
  {
    json: {
      ...$json,
      status: "rejected",
      message: "Invalid AdvSOC security-alert payload",
      errors: $json.validation?.errors ?? []
    }
  }
];

const text = [
  $json.description,
  $json.source_ip,
  $json.destination_ip,
  $json.domain,
  $json.url,
  $json.file_hash
]
.filter(Boolean)
.join(' ');

// IPv4 candidates
const ipCandidates =
  text.match(/\b(?:\d{1,3}\.){3}\d{1,3}\b/g) ?? [];

// Validate each octet
const ips = ipCandidates.filter(ip =>
  ip.split('.').every(part => {
    const n = Number(part);
    return n >= 0 && n <= 255;
  })
);

// URLs
const urls =
  text.match(/\bhttps?:\/\/[^\s<>"']+/gi) ?? [];

// Domains
const domains = [];

if ($json.domain) {
  domains.push($json.domain.toLowerCase());
}

for (const url of urls) {
  try {
    domains.push(new URL(url).hostname.toLowerCase());
  } catch {}
}

const descriptionDomains =
  ($json.description ?? '').match(
    /\b(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}\b/gi
  ) ?? [];

domains.push(...descriptionDomains.map(x => x.toLowerCase()));

// MD5 / SHA-1 / SHA-256
const hashes =
  text.match(
    /\b(?:[A-Fa-f0-9]{64}|[A-Fa-f0-9]{40}|[A-Fa-f0-9]{32})\b/g
  ) ?? [];

const unique = arr => [...new Set(arr)];

return [{
  json: {
    ...$json,

    iocs: {
      ips: unique(ips),
      domains: unique(domains),
      urls: unique(urls),
      hashes: unique(hashes.map(x => x.toLowerCase()))
    }
  }
}];

const description = ($json.description ?? '').toLowerCase();
const alertType = ($json.alert_type ?? '').toLowerCase();
const username = ($json.username ?? '').toLowerCase();
const originalSeverity =
  ($json.original_severity ?? '').toLowerCase();

const text = `${alertType} ${description}`;

let score = 0;
const matchedRules = [];

function addRule(id, points, evidence) {
  score += points;

  matchedRules.push({
    rule: id,
    points,
    evidence
  });
}

// ============================================================
// Helpers
// ============================================================

const ones = {
  zero: 0,
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8,
  nine: 9,
  ten: 10,
  eleven: 11,
  twelve: 12,
  thirteen: 13,
  fourteen: 14,
  fifteen: 15,
  sixteen: 16,
  seventeen: 17,
  eighteen: 18,
  nineteen: 19
};

const tens = {
  twenty: 20,
  thirty: 30,
  forty: 40,
  fifty: 50,
  sixty: 60,
  seventy: 70,
  eighty: 80,
  ninety: 90
};

function parseNumber(value) {
  if (!value) return null;

  const normalized = value
    .toLowerCase()
    .replace(/-/g, ' ')
    .trim();

  if (/^\d+$/.test(normalized)) {
    return Number(normalized);
  }

  if (Object.prototype.hasOwnProperty.call(ones, normalized)) {
    return ones[normalized];
  }

  if (Object.prototype.hasOwnProperty.call(tens, normalized)) {
    return tens[normalized];
  }

  const parts = normalized.split(/\s+/);

  if (
    parts.length === 2 &&
    Object.prototype.hasOwnProperty.call(tens, parts[0]) &&
    Object.prototype.hasOwnProperty.call(ones, parts[1])
  ) {
    return tens[parts[0]] + ones[parts[1]];
  }

  return null;
}

// Phrases such as:
// "does not clearly match malware, phishing..."
// should not become positive threat evidence just because they
// contain security-category words.
const taxonomyNegated =
  /\b(?:does not|doesn't|did not)\s+(?:clearly\s+)?match\b/.test(description) ||
  /\binsufficient (?:evidence|information)\b/.test(description) ||
  /\bno (?:confirmed |clear )?(?:malicious|attack|malware|phishing|reconnaissance) (?:evidence|indicator|indicators|activity)\b/.test(description);

// Strong alert types supplied by the source system.
const typeIsAuth =
  /^(?:suspicious_authentication|authentication_alert|brute_force)$/.test(alertType);

const typeIsNetwork =
  /^(?:malicious_network_activity|c2_activity|exfiltration)$/.test(alertType);

const typeIsPhishing =
  /^(?:phishing|phishing_detection)$/.test(alertType);

const typeIsMalware =
  /^(?:malware_detection|malware)$/.test(alertType);

const typeIsRecon =
  /^(?:reconnaissance|reconnaissance_scanning|port_scan)$/.test(alertType);

// ============================================================
// Authentication
// ============================================================

const numberExpression =
  '(\\d+|' +
  '(?:one|two|three|four|five|six|seven|eight|nine|ten|' +
  'eleven|twelve|thirteen|fourteen|fifteen|sixteen|' +
  'seventeen|eighteen|nineteen|' +
  'twenty|thirty|forty|fifty|sixty|seventy|eighty|ninety)' +
  '(?:[-\\s](?:one|two|three|four|five|six|seven|eight|nine))?' +
  ')';

const failedRegex = new RegExp(
  `\\b${numberExpression}\\s+` +
  `(?:failed|unsuccessful)\\s+` +
  `(?:login|logins|authentication)` +
  `(?:\\s+attempts?)?\\b`,
  'i'
);

const failedMatch = description.match(failedRegex);

let failureVolumeDetected = false;

if (failedMatch) {
  const attempts = parseNumber(failedMatch[1]);

  if (attempts !== null) {
    failureVolumeDetected = true;

    if (attempts >= 20) {
      addRule(
        'AUTH_HIGH_VOLUME_FAILURES',
        25,
        `${attempts} failed authentication attempts`
      );
    } else if (attempts >= 5) {
      addRule(
        'AUTH_REPEATED_FAILURES',
        20,
        `${attempts} repeated failed authentication attempts`
      );
    }
  }
}

// Handles phrases such as:
// "numerous failed login attempts"
// "repeated failed authentication attempts"
// "many unsuccessful logins"
if (
  !failureVolumeDetected &&
  /\b(?:numerous|many|multiple|repeated|several)\s+(?:failed|unsuccessful)\s+(?:login|logins|authentication)(?:\s+attempts?)?\b/.test(description)
) {
  failureVolumeDetected = true;

  addRule(
    'AUTH_REPEATED_FAILURES',
    20,
    'Repeated or numerous failed authentication attempts'
  );
}

if (
  /brute[\s-]?force|password spraying|password spray/.test(text)
) {
  addRule(
    'AUTH_BRUTE_FORCE_LANGUAGE',
    25,
    'Alert explicitly indicates brute-force or password-spraying activity'
  );
}

const successfulAuthentication =
  /\bsuccessful (?:login|authentication)\b/.test(description) ||
  /\bsuccessfully authenticated\b/.test(description) ||
  /\bauthentication succeeded\b/.test(description);

const priorAuthenticationFailures =
  /\bfailed (?:login|authentication)\b/.test(description) ||
  /\bunsuccessful (?:login|authentication)\b/.test(description) ||
  /\bbrute[\s-]?force\b/.test(description) ||
  /\bpassword spray(?:ing)?\b/.test(description) ||
  failureVolumeDetected;

if (
  successfulAuthentication &&
  priorAuthenticationFailures
) {
  addRule(
    'AUTH_SUCCESS_AFTER_FAILURES',
    20,
    'Successful authentication occurred after suspicious failures'
  );
}

// ============================================================
// Privileged account
// ============================================================

if (
  /admin|administrator|privileged|\broot\b/.test(
    `${username} ${description}`
  )
) {
  addRule(
    'PRIVILEGED_IDENTITY',
    20,
    'Privileged account or identity involved'
  );
}

// ============================================================
// Threat indicators
// ============================================================

const malwareLanguage =
  /malware|ransomware|trojan|malicious executable|known malicious file/.test(text);

const phishingLanguage =
  /phishing|credential harvesting|credential-harvesting/.test(text);

const reconLanguage =
  /port scan|port scanning|reconnaissance|enumeration/.test(text);

const c2Language =
  /command[\s-]and[\s-]control|\bc2\b|data exfiltration|exfiltration/.test(text);

// Only treat descriptive keywords as positive evidence when they
// aren't merely being mentioned in a negated/uncertain taxonomy statement.

const malwareDetected =
  typeIsMalware ||
  (!taxonomyNegated && malwareLanguage);

const phishingDetected =
  typeIsPhishing ||
  (!taxonomyNegated && phishingLanguage);

const reconDetected =
  typeIsRecon ||
  (!taxonomyNegated && reconLanguage);

const c2Detected =
  (!taxonomyNegated && c2Language);

// ============================================================
// Malware
// ============================================================

const containedSuspiciousMalware =
  typeIsMalware &&
  /\bsuspicious (?:executable|file|binary|process)\b/.test(description) &&
  /\b(?:quarantined|contained|blocked)\b/.test(description) &&
  !/\b(?:ransomware|trojan|malicious executable|known malicious file)\b/.test(description);

if (malwareDetected) {

  if (containedSuspiciousMalware) {

    addRule(
      'MALWARE_SUSPICIOUS_CONTAINED',
      20,
      'Suspicious executable detected and already contained; maliciousness not independently confirmed'
    );

  } else {

    addRule(
      'MALWARE_INDICATOR',
      45,
      'Alert indicates confirmed or strongly supported malware activity'
    );
  }
}

// ============================================================
// Phishing
// ============================================================

if (phishingDetected) {
  addRule(
    'PHISHING_INDICATOR',
    30,
    'Alert contains phishing-related evidence'
  );
}

// ============================================================
// Reconnaissance
// ============================================================

if (reconDetected) {
  addRule(
    'RECON_ACTIVITY',
    20,
    'Reconnaissance or scanning behavior detected'
  );
}

// ============================================================
// C2 / exfiltration
// ============================================================

if (c2Detected) {
  addRule(
    'C2_OR_EXFILTRATION',
    50,
    'Command-and-control or exfiltration evidence detected'
  );
}

// ============================================================
// Original source severity
// ============================================================

const severityWeights = {
  medium: 5,
  high: 10,
  critical: 15
};

if (severityWeights[originalSeverity]) {
  addRule(
    'SOURCE_SEVERITY',
    severityWeights[originalSeverity],
    `Source marked alert as ${originalSeverity}`
  );
}

// Keep deterministic evidence bounded.
// Final severity is still decided by the downstream scoring stage.
score = Math.min(score, 60);

// ============================================================
// Preliminary category
// ============================================================

let category = 'other_unknown';

// Strong source alert types take priority.
if (typeIsNetwork) {
  category = 'malicious_network_activity';

} else if (typeIsMalware) {
  category = 'malware_malicious_file';

} else if (typeIsPhishing) {
  category = 'phishing_malicious_url';

} else if (typeIsRecon) {
  category = 'reconnaissance_scanning';

} else if (typeIsAuth) {
  category = 'suspicious_authentication';

// Then use non-negated evidence from the description.
} else if (c2Detected) {
  category = 'malicious_network_activity';

} else if (malwareDetected) {
  category = 'malware_malicious_file';

} else if (phishingDetected) {
  category = 'phishing_malicious_url';

} else if (
  !taxonomyNegated &&
  (
    failureVolumeDetected ||
    /failed (?:login|authentication)|brute[\s-]?force|password spray/.test(text)
  )
) {
  category = 'suspicious_authentication';

} else if (reconDetected) {
  category = 'reconnaissance_scanning';

// Explicit informational/normal activity can be benign.
} else if (
  alertType === 'informational' &&
  score === 0
) {
  category = 'benign_informational';

} else if (
  score === 0 &&
  /\b(?:normal|approved|scheduled|expected|routine|known corporate)\b/.test(description)
) {
  category = 'benign_informational';

} else {
  category = 'other_unknown';
}

return [{
  json: {
    ...$json,

    rule_result: {
      preliminary_category: category,
      rule_score: score,
      matched_rules: matchedRules
    }
  }
}];

const original = $('Select Primary IoC').item.json;

const results = $json.data ?? [];

const hit =
  Array.isArray(results)
    ? results[0]
    : results;

if (!hit) {
  return [{
    json: {
      ...original,

      threat_intel_findings: {
        provider: 'virustotal',
        lookup_status: 'not_found',

        ioc_type: original.vt_ioc_type,
        ioc_value: original.vt_query,

        object_type: null,

        malicious: 0,
        suspicious: 0,
        harmless: 0,
        undetected: 0,

        reputation: null
      }
    }
  }];
}

const attributes = hit.attributes ?? {};
const stats = attributes.last_analysis_stats ?? {};

return [{
  json: {
    ...original,

    threat_intel_findings: {
      provider: 'virustotal',
      lookup_status: 'found',

      ioc_type: original.vt_ioc_type,
      ioc_value: original.vt_query,

      object_type: hit.type ?? null,

      malicious: Number(stats.malicious ?? 0),
      suspicious: Number(stats.suspicious ?? 0),
      harmless: Number(stats.harmless ?? 0),
      undetected: Number(stats.undetected ?? 0),

      reputation:
        attributes.reputation !== undefined
          ? Number(attributes.reputation)
          : null
    }
  }
}];

return [{
  json: {
    ...$json,

    threat_intel_findings: {
      provider: 'virustotal',
      lookup_status: 'no_ioc',

      ioc_type: null,
      ioc_value: null,
      object_type: null,

      malicious: 0,
      suspicious: 0,
      harmless: 0,
      undetected: 0,

      reputation: null
    }
  }
}];

const original = $('AI prepare context').item.json;

const ai = $json.output ?? $json;

return [{
  json: {
    ...original,

    ai_status: 'success',

    ai_result: {
      category:
        ai.category ??
        original.rule_result?.preliminary_category ??
        'other_unknown',

      confidence:
        Number(ai.confidence ?? 0),

      summary:
        String(ai.summary ?? ''),

      explanation:
        String(ai.explanation ?? ''),

      recommended_action:
        String(
          ai.recommended_action ??
          'Human analyst review is recommended.'
        ),

      mitre_attack_mapping:
        Array.isArray(ai.mitre_attack_mapping)
          ? ai.mitre_attack_mapping
          : []
    }
  }
}];

const original =
  $('AI prepare context').item.json;

return [{
  json: {
    ...original,

    ai_status: 'fallback',

    ai_result: {
      category:
        original.rule_result?.preliminary_category ??
        'other_unknown',

      confidence: 0,

      summary:
        'AI classifier unavailable; deterministic analysis retained.',

      explanation:
        'AdvSOC continued in degraded mode using deterministic security evidence.',

      recommended_action:
        'Human analyst review is recommended.',

      mitre_attack_mapping: []
    }
  }
}];

const rule = $json.rule_result ?? {};
const vt = $json.threat_intel_findings ?? {};
const ai = $json.ai_result ?? {};

const alertType = ($json.alert_type ?? '').toLowerCase();
const description = ($json.description ?? '').toLowerCase();
const originalSeverity =
  ($json.original_severity ?? '').toLowerCase();

const ruleScore = Math.min(
  60,
  Math.max(0, Number(rule.rule_score ?? 0))
);

const matchedRules =
  Array.isArray(rule.matched_rules)
    ? rule.matched_rules
    : [];

const matchedRuleIds =
  matchedRules.map(r => r.rule);

// ============================================================
// VirusTotal — max 25
// ============================================================

const malicious = Number(vt.malicious ?? 0);
const suspicious = Number(vt.suspicious ?? 0);

const reputation =
  vt.reputation === null || vt.reputation === undefined
    ? null
    : Number(vt.reputation);

const iocValue =
  String(vt.ioc_value ?? '').toLowerCase();

// Don't let synthetic/reserved test indicators distort evaluation.
function isReservedTestIndicator(value) {
  if (!value) return false;

  if (
    /^203\.0\.113\./.test(value) ||
    /^198\.51\.100\./.test(value) ||
    /^192\.0\.2\./.test(value) ||
    /^127\./.test(value) ||
    /^10\./.test(value) ||
    /^192\.168\./.test(value) ||
    /^172\.(1[6-9]|2\d|3[01])\./.test(value)
  ) {
    return true;
  }

  if (
    /\.invalid(?:\/|$)/.test(value) ||
    /\.test(?:\/|$)/.test(value) ||
    /\.localhost(?:\/|$)/.test(value)
  ) {
    return true;
  }

  return false;
}

const ignoreThreatIntel =
  isReservedTestIndicator(iocValue);

let threatIntelScore = 0;

if (
  vt.lookup_status === 'found' &&
  !ignoreThreatIntel
) {
  if (malicious >= 10) {
    threatIntelScore = 25;
  } else if (malicious >= 3) {
    threatIntelScore = 20;
  } else if (malicious >= 1) {
    threatIntelScore = 15;
  } else if (suspicious >= 3) {
    threatIntelScore = 10;
  } else if (suspicious >= 1) {
    threatIntelScore = 5;
  }

  if (
    reputation !== null &&
    reputation < 0
  ) {
    threatIntelScore = Math.min(
      25,
      threatIntelScore + 5
    );
  }
}

// ============================================================
// AI — max 15
// ============================================================

const confidence = Math.min(
  1,
  Math.max(0, Number(ai.confidence ?? 0))
);

const categoryWeights = {
  benign_informational: 0,
  suspicious_authentication: 8,
  malicious_network_activity: 15,
  phishing_malicious_url: 15,
  malware_malicious_file: 15,
  reconnaissance_scanning: 8,
  other_unknown: 3
};

const aiBase =
  categoryWeights[ai.category] ?? 3;

let aiScore = 0;

if ($json.ai_status === 'success') {
  aiScore =
    Math.round(aiBase * confidence);
}

// Explicitly uncertain/unknown alerts should not be pushed
// aggressively upward by an overconfident LLM alone.
const explicitlyUncertain =
  alertType === 'unknown_event' &&
  (
    /insufficient (?:evidence|information)/.test(description) ||
    /does not clearly match/.test(description) ||
    /no confirmed malicious indicators/.test(description) ||
    /insufficient to determine malicious intent/.test(description)
  );

if (explicitlyUncertain) {
  aiScore = Math.min(aiScore, 3);
}

// ============================================================
// Combined raw risk
// ============================================================

let riskScore =
  ruleScore +
  threatIntelScore +
  aiScore;

riskScore = Math.min(
  100,
  Math.max(0, riskScore)
);

const appliedFloors = [];

function applyFloor(value, reason) {
  if (riskScore < value) {
    riskScore = value;
    appliedFloors.push(
      `${value}: ${reason}`
    );
  }
}

// ============================================================
// Evidence-based CRITICAL floors
// ============================================================

// Critical C2/exfiltration alert from the source.
if (
  matchedRuleIds.includes('C2_OR_EXFILTRATION') &&
  originalSeverity === 'critical'
) {
  applyFloor(
    75,
    'Critical source severity with C2/exfiltration evidence'
  );
}

// Privileged account successfully accessed after suspicious failures.
if (
  matchedRuleIds.includes('PRIVILEGED_IDENTITY') &&
  matchedRuleIds.includes('AUTH_SUCCESS_AFTER_FAILURES') &&
  originalSeverity === 'critical'
) {
  applyFloor(
    75,
    'Critical privileged-account compromise pattern'
  );
}

// Critical malware detection.
if (
  matchedRuleIds.includes('MALWARE_INDICATOR') &&
  originalSeverity === 'critical'
) {
  applyFloor(
    75,
    'Critical source severity with malware evidence'
  );
}

// Strong independent threat-intel confirmation.
if (
  matchedRuleIds.includes('C2_OR_EXFILTRATION') &&
  malicious >= 1 &&
  !ignoreThreatIntel
) {
  applyFloor(
    75,
    'C2/exfiltration corroborated by malicious threat intelligence'
  );
}

// ============================================================
// Evidence-based HIGH floors
// ============================================================

if (
  matchedRuleIds.includes('PHISHING_INDICATOR') &&
  originalSeverity === 'high'
) {
  applyFloor(
    50,
    'High-severity phishing evidence'
  );
}

if (
  matchedRuleIds.includes('RECON_ACTIVITY') &&
  originalSeverity === 'high'
) {
  applyFloor(
    50,
    'High-severity reconnaissance evidence'
  );
}

if (
  matchedRuleIds.includes('MALWARE_INDICATOR') &&
  originalSeverity === 'high'
) {
  applyFloor(
    50,
    'High-severity malware evidence'
  );
}

if (
  matchedRuleIds.includes('C2_OR_EXFILTRATION') &&
  originalSeverity === 'high'
) {
  applyFloor(
    50,
    'High-severity C2/exfiltration evidence'
  );
}

// ============================================================
// Evidence-based MEDIUM floors
// ============================================================

// A source explicitly identifying malicious network activity
// at medium severity should not collapse to Low merely because
// enrichment is unavailable.
if (
  alertType === 'malicious_network_activity' &&
  originalSeverity === 'medium'
) {
  applyFloor(
    25,
    'Medium source severity with malicious-network alert type'
  );
}

// ============================================================
// Severity
// ============================================================

let severity;

if (riskScore >= 75) {
  severity = 'critical';
} else if (riskScore >= 50) {
  severity = 'high';
} else if (riskScore >= 25) {
  severity = 'medium';
} else {
  severity = 'low';
}

// ============================================================
// Final category
// ============================================================

let finalCategory =
  rule.preliminary_category ??
  'other_unknown';

// Normally, a sufficiently confident AI result may refine
// the deterministic preliminary category.
//
// But explicit "unknown / insufficient evidence" alerts should
// remain unknown unless deterministic evidence independently
// establishes another category.
if (
  $json.ai_status === 'success' &&
  confidence >= 0.60 &&
  ai.category &&
  ai.category !== 'other_unknown' &&
  !(
    explicitlyUncertain &&
    rule.preliminary_category === 'other_unknown'
  )
) {
  finalCategory = ai.category;
}

// ============================================================
// Explanation
// ============================================================

const ruleEvidence =
  matchedRules.length
    ? matchedRules
        .map(
          r =>
            `${r.rule}: ${r.evidence}`
        )
        .join('; ')
    : 'No deterministic rules matched';

const floorEvidence =
  appliedFloors.length
    ? `Applied evidence floors: ${appliedFloors.join('; ')}`
    : 'No evidence floor applied';

const threatIntelNote =
  ignoreThreatIntel
    ? 'Threat-intelligence score suppressed for reserved/test indicator'
    : `VirusTotal malicious=${malicious}, suspicious=${suspicious}`;

const explanation = [
  `Rule score ${ruleScore}/60`,
  `Threat-intelligence score ${threatIntelScore}/25`,
  `AI score ${aiScore}/15`,
  ruleEvidence,
  threatIntelNote,
  `AI confidence=${Math.round(confidence * 100)}%`,
  floorEvidence
].join(' | ');

return [{
  json: {
    ...$json,

    scoring: {
      rule_score: ruleScore,
      threat_intel_score: threatIntelScore,
      ai_score: aiScore,
      evidence_floors: appliedFloors,
      test_indicator_ti_suppressed:
        ignoreThreatIntel
    },

    risk_score: riskScore,
    severity,
    final_category: finalCategory,

    summary:
      ai.summary ||
      'AdvSOC security assessment completed.',

    explanation,

    recommended_action:
      ai.recommended_action ||
      'Review available security evidence.',

    mitre_attack_mapping:
      Array.isArray(ai.mitre_attack_mapping)
        ? ai.mitre_attack_mapping
        : []
  }
}];

const severity =
  ($json.severity ?? 'low').toLowerCase();

const category =
  $json.final_category ?? 'other_unknown';

let actionCode = 'log_only';

// --------------------
// Choose response
// --------------------

if (severity === 'low') {

  actionCode = 'log_only';

} else if (severity === 'medium') {

  actionCode = 'investigate';

} else if (severity === 'high') {

  if (category === 'malware_malicious_file') {
    actionCode = 'isolate_host';

  } else if (
    category === 'suspicious_authentication' ||
    category === 'malicious_network_activity' ||
    category === 'phishing_malicious_url'
  ) {
    actionCode = 'block_indicator';

  } else {
    actionCode = 'escalate';
  }

} else if (severity === 'critical') {

  if (category === 'suspicious_authentication') {
    actionCode = 'disable_account';

  } else if (
    category === 'malware_malicious_file' ||
    category === 'malicious_network_activity'
  ) {
    actionCode = 'isolate_host';

  } else {
    actionCode = 'contain_and_escalate';
  }
}

// --------------------
// Deterministic policy
// --------------------

const automaticActions = [
  'log_only',
  'investigate',
  'escalate'
];

const approvalActions = [
  'block_indicator',
  'isolate_host',
  'disable_account',
  'contain_and_escalate',
  'quarantine_file'
];

const forbiddenActions = [
  'delete_logs',
  'wipe_host',
  'disable_security_controls'
];

let policyDecision = 'review';
let humanApprovalRequired = true;

if (automaticActions.includes(actionCode)) {

  policyDecision = 'allow';
  humanApprovalRequired = false;

} else if (approvalActions.includes(actionCode)) {

  policyDecision = 'review';
  humanApprovalRequired = true;

} else if (forbiddenActions.includes(actionCode)) {

  policyDecision = 'block';
  humanApprovalRequired = false;
}

return [{
  json: {
    ...$json,

    action_code: actionCode,
    policy_decision: policyDecision,
    human_approval_required: humanApprovalRequired,

    // No real blocking/isolation/account disabling in V1
    action_execution: 'simulated'
  }
}];

const iocs = $json.iocs ?? {};

let type = null;
let value = null;

// V1 priority
if (iocs.hashes?.length) {
  type = 'hash';
  value = iocs.hashes[0];

} else if (iocs.urls?.length) {
  type = 'url';
  value = iocs.urls[0];

} else if (iocs.domains?.length) {
  type = 'domain';
  value = iocs.domains[0];

} else if (iocs.ips?.length) {
  type = 'ip';
  value = iocs.ips[0];
}

return [{
  json: {
    ...$json,

    vt_lookup_needed: Boolean(value),
    vt_ioc_type: type,
    vt_query: value ?? ''
  }
}];

const original = $('Build Result').item.json;

return [{
  json: original
}];

const original = $('Select Primary IoC').item.json;

return [{
  json: {
    ...original,
    threat_intel_findings: {
      provider: "VirusTotal",
      lookup_status: "unavailable",
      ioc_type: original.vt_ioc_type ?? null,
      ioc_value: original.vt_query ?? null,
      malicious: 0,
      suspicious: 0,
      harmless: 0,
      undetected: 0,
      reputation: 0
    }
  }
}];
